<?php
use Illuminate\Support\Facades\Route;
use Semizzy\Addons\EventsEntertainment\Http\Controllers\AdminEventController;
use Semizzy\Addons\EventsEntertainment\Http\Controllers\AdminEventPaymentController;
Route::middleware(['web','auth','ensure.addon:events.entertainment','permission:events.manage'])->prefix('admin/events')->group(function(){Route::get('/',[AdminEventController::class,'index'])->name('admin.events.index');Route::post('/',[AdminEventController::class,'store'])->name('admin.events.store');Route::post('/venues',[AdminEventController::class,'storeVenue'])->name('admin.events.venues.store');Route::post('/ticket-types',[AdminEventController::class,'storeTicketType'])->name('admin.events.ticket-types.store');Route::post('/orders/{order}/manual-payment',[AdminEventPaymentController::class,'confirm'])->name('admin.events.orders.manual-payment');});